import { traverseTree } from '../../../exported-utils/tree/tree-utils';
export function convertChipsToMenuOptions(chips, context, removeChipInfo) {
    if (chips != null) {
        const filterMenuOption = chips.map((chip) => {
            return {
                id: chip.id,
                isDisabled: () => { return (context.getAttribute('disabled') === 'true' || chip.disabled === true) ? true : false; },
                disabledTooltipText: 'Selection Unavailable',
                text: chip.dataText,
                subtext: chip.dataSubtext,
                tooltipText: chip.dataTooltip,
                iconRight: (context.getAttribute('disabled') === 'true' || context.getAttribute('data-is-read-only') === 'true' || chip.dataIsReadOnly === true || chip.disabled === true) ? undefined : 'circle-close',
                options: chip.children,
                menuOptionChildren: convertChipsToMenuOptions(chip.children, context, {
                    parentId: chip.id,
                    removeText: removeChipInfo.removeText
                }),
                dataShowAvatar: chip.dataShowAvatar,
                avatarFirstName: chip.dataAvatarFirstName,
                avatarLastName: chip.dataAvatarLastName,
                avatarProfilePictureSrc: chip.dataAvatarProfilePictureSrc,
                controlType: (context.getAttribute('data-is-read-only') === 'true' || chip.dataIsReadOnly === true) ? 'none' : 'button',
                onClickCallback: (menuOption, callbackContext, event) => {
                    context.dispatchEvent(new CustomEvent('neonChipRemove', { bubbles: true, detail: {
                            chipId: chip.id,
                            menuOption: menuOption
                        } }));
                },
            };
        });
        if (removeChipInfo.parentId != null && !isAnyChipHasChildren(chips) && chips.length > 1 && !isChipsHasDisabledChildren(chips)) {
            // context is component instance i,e. ex: chipset
            if (context.getAttribute('disabled') !== 'true' && context.getAttribute('data-is-read-only') !== 'true') {
                filterMenuOption.unshift({
                    id: removeChipInfo.parentId + '-remove-all',
                    text: removeChipInfo.removeText,
                    iconRight: 'circle-close',
                    onClickCallback: () => {
                        context.dispatchEvent(new CustomEvent('neonChipRemove', { bubbles: true, detail: { chipId: removeChipInfo.parentId } }));
                    },
                });
            }
        }
        return filterMenuOption;
    }
}
function isAnyChipHasChildren(chips) {
    for (const chip of chips) {
        if (chip.children != null && chip.children.length > 0) {
            return true;
        }
    }
    return false;
}
function isChipsHasDisabledChildren(chips) {
    let hasDisabledChildren = false;
    if (chips != null && chips.length > 0) {
        traverseTree(chips, (chip) => {
            if (chip.dataIsReadOnly === true || chip.disabled === true) {
                hasDisabledChildren = true;
                return true;
            }
        });
    }
    return hasDisabledChildren;
}
export function isChipValuesEqual(chip1, chip2) {
    if ((chip1.children != null && chip2.children == null) ||
        (chip1.children == null && chip2.children != null)) {
        //We do this test first because it's really fast and if it fails
        //we don't have to test everything else.
        return false;
    }
    const chipPropsEqual = chip1.id === chip2.id &&
        chip1.dataText === chip2.dataText &&
        chip1.dataSubtext === chip2.dataSubtext &&
        chip1.dataSize === chip2.dataSize &&
        chip1.dataTooltip === chip2.dataTooltip &&
        chip1.dataTooltipPosition === chip2.dataTooltipPosition &&
        chip1.dataShowAvatar === chip2.dataShowAvatar &&
        chip1.dataAvatarFirstName === chip2.dataAvatarFirstName &&
        chip1.dataAvatarLastName === chip2.dataAvatarLastName &&
        chip1.dataAvatarProfilePictureSrc === chip2.dataAvatarProfilePictureSrc &&
        chip1.dataAvatarBackgroundOption === chip2.dataAvatarBackgroundOption &&
        chip1.disabled === chip2.disabled &&
        chip1.dataIsReadOnly === chip2.dataIsReadOnly &&
        chip1.dataIsOnGray === chip2.dataIsOnGray;
    if (chip1.children != null && chip2.children != null) {
        //Ok, now we need to check the children because we know they are both not null.
        if (chip1.children.length !== chip2.children.length) {
            return false;
        }
        for (let i = 0; i < chip1.children.length; i++) {
            const isChildEqual = isChipValuesEqual(chip1.children[i], chip2.children[i]);
            if (!isChildEqual) {
                return false;
            }
        }
        return true;
    }
    else {
        return chipPropsEqual;
    }
}
